template.solver:
def solve(a1, t1, a2, t2, n1, n2):
    best = None
    for x in range(n1 + 1):
        for y in range(n2 + 1):
            A = a1 * x + a2 * y
            T = t1 * (n1 - x) + t2 * (n2 - y)
            m = max(A, T)
            if best is None or m < best:
                best = m
    return best
